<script setup>
import { onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue';
import { Head, router } from '@inertiajs/vue3';
import AdminLayout from '../../../Layouts/AdminLayout.vue';
import DataPanel from '../../../Components/Ui/DataPanel.vue';
import EmptyState from '../../../Components/Ui/EmptyState.vue';
import PageHeader from '../../../Components/Ui/PageHeader.vue';
import StatRail from '../../../Components/Ui/StatRail.vue';
defineOptions({layout:AdminLayout});
const props=defineProps({invoice:{type:Object,required:true},items:{type:Array,default:()=>[]},payments:{type:Array,default:()=>[]},can:{type:Object,required:true},defaults:{type:Object,required:true},urls:{type:Object,required:true}});
const dialog=ref('');const processing=ref(false);const errors=ref({});const payment=reactive({amount:props.invoice.amounts.balanceRaw,method:'cash',paid_on:props.defaults.paymentDate,exchange_rate:'',reference:'',notes:''});const reason=ref('');
function close(){if(processing.value)return;dialog.value='';errors.value={}}
function submitPayment(){processing.value=true;errors.value={};router.post(props.urls.pay,{...payment},{preserveScroll:true,onError:e=>errors.value=e,onSuccess:close,onFinish:()=>processing.value=false})}
function submitCancel(){if(!reason.value.trim())return;processing.value=true;errors.value={};router.post(props.urls.cancel,{reason:reason.value.trim()},{preserveScroll:true,onError:e=>errors.value=e,onSuccess:close,onFinish:()=>processing.value=false})}
const key=e=>{if(e.key==='Escape')close()};watch(dialog,v=>document.body.style.overflow=v?'hidden':'');onMounted(()=>window.addEventListener('keydown',key));onBeforeUnmount(()=>{window.removeEventListener('keydown',key);document.body.style.overflow=''})
</script>
<template>
<Head :title="invoice.number"/>
<PageHeader :title="`فاتورة ${invoice.number}`" icon="bi-receipt-cutoff" :subtitle="invoice.supplierName" :crumbs="[{label:'فواتير الموردين',url:urls.index}]"><template #actions><a v-if="invoice.attachmentUrl" :href="invoice.attachmentUrl" target="_blank" class="btn btn-light"><i class="bi bi-paperclip"></i> المرفق</a><button v-if="can.pay" type="button" class="btn btn-success" @click="dialog='pay'"><i class="bi bi-cash-coin"></i> تسجيل دفعة</button><button v-if="can.cancel" type="button" class="btn btn-outline-danger" @click="dialog='cancel'"><i class="bi bi-x-circle"></i> إلغاء الفاتورة</button></template></PageHeader>
<StatRail :stats="[{label:'الحالة',value:invoice.statusLabel,icon:'bi-info-circle',color:invoice.statusColor==='warning'?'accent':invoice.statusColor},{label:'إجمالي الفاتورة',value:invoice.amounts.total,icon:'bi-receipt',color:'primary'},{label:'مدفوع',value:invoice.amounts.paid,icon:'bi-check-circle-fill',color:'success'},{label:'متبقي',value:invoice.amounts.balance,icon:'bi-alarm',color:invoice.amounts.balanceRaw>0?'danger':'muted'}]"/>
<div class="invoice-layout">
 <aside>
  <DataPanel title="بيانات الفاتورة" icon="bi-info-circle"><div class="facts"><div><small>المورد</small><strong>{{invoice.supplierName}}</strong></div><div><small>رقم الفاتورة</small><strong>{{invoice.number}}</strong></div><div v-if="invoice.purchaseOrder"><small>أمر الشراء</small><a :href="invoice.purchaseOrder.url">{{invoice.purchaseOrder.number}}</a></div><div><small>تاريخ الفاتورة</small><strong>{{invoice.invoiceDate}}</strong></div><div v-if="invoice.dueDate"><small>الاستحقاق</small><strong>{{invoice.dueDate}}</strong></div><div><small>العملة</small><strong>{{invoice.currency}}</strong></div><div v-if="invoice.currency!==invoice.baseCurrency"><small>سعر الصرف إلى {{invoice.baseCurrency}}</small><strong>{{invoice.exchangeRate}}</strong></div><div v-if="invoice.creatorName"><small>أنشأها</small><strong>{{invoice.creatorName}}</strong></div></div><div v-if="invoice.notes" class="notes"><small>ملاحظات</small><p>{{invoice.notes}}</p></div></DataPanel>
  <DataPanel title="الحساب" icon="bi-calculator"><div class="money"><span><small>الفرعي</small><b>{{invoice.amounts.subtotal}}</b></span><span v-if="invoice.amounts.taxRaw>0"><small>ضريبة المورد</small><b>{{invoice.amounts.tax}}</b></span><strong><small>الإجمالي</small><b>{{invoice.amounts.total}}</b></strong><span><small>المدفوع</small><b class="paid">{{invoice.amounts.paid}}</b></span><strong class="balance"><small>المتبقي</small><b>{{invoice.amounts.balance}}</b></strong></div></DataPanel>
 </aside>
 <main>
  <DataPanel title="مطابقة بنود الفاتورة مع الاستلام" :count="items.length" icon="bi-list-check"><div v-if="items.length" class="item-list"><article v-for="item in items" :key="item.id" :class="{variance:item.hasQtyVariance||item.hasTotalVariance}"><div><strong>{{item.description}}</strong><small>{{item.unit}}</small></div><span><small>على الفاتورة</small><b>{{item.quantity}}</b></span><span><small>المستلم</small><b>{{item.receivedQty}}</b></span><span><small>الإجمالي</small><b>{{item.total}}</b></span><span><small>فرق الكمية</small><b :class="{danger:item.hasQtyVariance}">{{item.qtyVariance}}</b></span><span><small>فرق القيمة</small><b :class="{danger:item.hasTotalVariance}">{{item.totalVariance}}</b></span></article></div><EmptyState v-else compact icon="bi-list-ul" title="فاتورة بإجمالي فقط" message="لا توجد بنود مفصلة للمطابقة."/></DataPanel>
  <DataPanel title="سجل الدفعات" :count="payments.length" icon="bi-cash-stack"><div v-if="payments.length" class="payment-list"><article v-for="pay in payments" :key="pay.id"><i class="bi" :class="pay.method==='نقدي'?'bi-cash':'bi-bank'"></i><div><strong>{{pay.amount}}</strong><small>{{pay.method}} · {{pay.date}}</small></div><span><small>بواسطة</small><b>{{pay.payer}}</b></span><span v-if="pay.reference"><small>المرجع</small><b>{{pay.reference}}</b></span><p v-if="pay.notes">{{pay.notes}}</p></article></div><EmptyState v-else compact icon="bi-cash-stack" title="لا دفعات بعد" message="سجّل الدفعة من أعلى الصفحة عندما يتم السداد."/></DataPanel>
 </main>
</div>
<div v-if="dialog" class="modal-shell" @click.self="close"><section class="modal-card"><header><span><i class="bi" :class="dialog==='pay'?'bi-cash-coin':'bi-x-circle'"></i><strong>{{dialog==='pay'?'تسجيل دفعة':'إلغاء الفاتورة'}}</strong></span><button type="button" @click="close"><i class="bi bi-x-lg"></i></button></header><form v-if="dialog==='pay'" @submit.prevent="submitPayment"><div class="balance-banner"><small>المتبقي على الفاتورة</small><strong>{{invoice.amounts.balance}}</strong></div><label><span>القيمة *</span><input v-model="payment.amount" type="number" step="0.01" min="0.01" :max="invoice.amounts.balanceRaw" required><small v-if="errors.amount">{{errors.amount}}</small></label><div class="method-picks"><button type="button" :class="{active:payment.method==='cash'}" @click="payment.method='cash'"><i class="bi bi-cash"></i> نقدي</button><button type="button" :class="{active:payment.method==='bank_transfer'}" @click="payment.method='bank_transfer'"><i class="bi bi-bank"></i> تحويل بنكي</button></div><label><span>التاريخ *</span><input v-model="payment.paid_on" type="date" required></label><label v-if="invoice.currency!==invoice.baseCurrency"><span>سعر الصرف يوم الدفع</span><input v-model="payment.exchange_rate" type="number" step="0.00000001" min="0.000001" :placeholder="`آخر سعر ${invoice.exchangeRate}`"></label><label><span>مرجع التحويل</span><input v-model="payment.reference" maxlength="100"></label><label><span>ملاحظات</span><textarea v-model="payment.notes" rows="2"></textarea></label><footer><button type="button" class="btn btn-light" @click="close">تراجع</button><button class="btn btn-success" :disabled="processing">تسجيل الدفعة</button></footer></form><form v-else @submit.prevent="submitCancel"><p class="cancel-warning">الإلغاء يعكس أثر الفاتورة المحاسبي ويحفظها في السجل كملغاة. لا تستخدمه لتصحيح دفعة.</p><label><span>سبب الإلغاء *</span><textarea v-model="reason" rows="4" required autofocus></textarea><small v-if="errors.reason">{{errors.reason}}</small></label><footer><button type="button" class="btn btn-light" @click="close">تراجع</button><button class="btn btn-danger" :disabled="processing||!reason.trim()">تأكيد الإلغاء</button></footer></form></section></div>
</template>
<style scoped>
.invoice-layout{display:grid;grid-template-columns:320px minmax(0,1fr);align-items:start;gap:11px}.invoice-layout aside,.invoice-layout main{display:grid;gap:10px}.facts{display:grid;grid-template-columns:1fr 1fr;gap:1px;padding:3px;background:#edf1ee}.facts>div{display:grid;padding:9px;background:#fff}.facts small,.money small,.item-list small,.payment-list small{color:#819087;font-size:.56rem}.facts strong,.facts a{color:#34463b;font-size:.65rem}.notes{margin-top:8px;padding:10px;border-inline-start:3px solid #b4d2bc;border-radius:8px;background:#f3f8f4}.notes small{color:#75847b;font-size:.56rem}.notes p{margin:3px 0 0;white-space:pre-wrap;font-size:.63rem}.money{display:grid;gap:7px}.money>span,.money>strong{display:flex;justify-content:space-between}.money b{font-size:.66rem}.money>strong{padding-top:8px;border-top:1px solid #dfe7e2;color:#176b39}.money>strong b{font-size:.8rem}.money .paid{color:#178044}.money .balance{margin-top:3px;padding:10px;border:0;border-radius:9px;color:#a42d2d;background:#fff0f0}.item-list,.payment-list{display:grid;gap:6px}.item-list article{display:grid;grid-template-columns:minmax(150px,1.2fr) repeat(5,minmax(75px,.65fr));align-items:center;gap:8px;padding:10px;border:1px solid #e1e8e3;border-radius:11px;background:#fff}.item-list article.variance{border-inline-start:4px solid #d88914;background:#fffbf3}.item-list article>div,.item-list article>span{display:grid}.item-list strong,.item-list b{font-size:.62rem}.item-list .danger{color:#b42318}.payment-list article{display:grid;grid-template-columns:38px minmax(130px,1fr) 1fr 1fr;align-items:center;gap:9px;padding:10px;border:1px solid #e1e8e3;border-radius:11px}.payment-list article>i{display:grid;width:36px;height:36px;place-items:center;border-radius:9px;color:#176b39;background:#eaf5ed}.payment-list article>div,.payment-list article>span{display:grid}.payment-list strong,.payment-list b{font-size:.63rem}.payment-list p{grid-column:2/-1;margin:0;color:#6f7d74;font-size:.59rem}.modal-shell{position:fixed;z-index:1200;inset:0;display:grid;place-items:center;padding:16px;background:rgba(14,29,20,.48);backdrop-filter:blur(3px)}.modal-card{width:min(470px,100%);max-height:90vh;overflow:auto;border-radius:17px;background:#fff;box-shadow:0 24px 70px rgba(0,0,0,.22)}.modal-card>header{display:flex;align-items:center;justify-content:space-between;padding:14px;border-bottom:1px solid #e6ece8}.modal-card>header span{display:flex;gap:8px}.modal-card>header button{display:grid;width:34px;height:34px;place-items:center;border:0;border-radius:9px;background:#f0f3f1}.modal-card form{display:grid;gap:10px;padding:14px}.modal-card label{display:grid;gap:4px}.modal-card label>span{font-size:.62rem;font-weight:850}.modal-card input,.modal-card textarea{width:100%;padding:9px;border:1px solid #d9e2dc;border-radius:9px;outline:0}.modal-card label small{color:#b42318;font-size:.56rem}.balance-banner{display:flex;align-items:center;justify-content:space-between;padding:10px;border-radius:10px;color:#176b39;background:#eef8f1}.balance-banner small{font-size:.59rem}.method-picks{display:grid;grid-template-columns:1fr 1fr;gap:7px}.method-picks button{min-height:42px;border:1px solid #dfe7e2;border-radius:10px;color:#65746b;background:#fff;font-weight:800}.method-picks button.active{color:#176b39;border-color:#98c7a6;background:#eef8f1}.modal-card footer{display:flex;justify-content:flex-end;gap:7px;padding-top:6px}.cancel-warning{margin:0;padding:10px;border-radius:10px;color:#9b2929;background:#fff0f0;font-size:.61rem;line-height:1.6}
@media(max-width:950px){.invoice-layout{grid-template-columns:1fr}.invoice-layout aside{grid-template-columns:1fr 1fr}.item-list article{grid-template-columns:minmax(150px,1.2fr) repeat(3,1fr)}.item-list article>span:nth-last-of-type(-n+2){display:none}}
@media(max-width:650px){.invoice-layout aside{grid-template-columns:1fr}.item-list article{grid-template-columns:1fr 1fr}.item-list article>div{grid-column:1/-1}.item-list article>span:nth-of-type(n+3){display:none}.payment-list article{grid-template-columns:36px 1fr}.payment-list article>span{grid-column:2}.payment-list p{grid-column:2}.facts{grid-template-columns:1fr}}
</style>
